import json, sys

for path in sys.argv[1:]:
    d = json.load(open(path))
    ml = d.get("media_list", d)
    cols = d.get("columns") or ml.get("columns") or []
    rows = d.get("rows") or ml.get("rows") or []
    print(f"\n=== {path} ===")
    print(f"list_id={ml.get('id')}  rows={len(rows)}")
    id_to_name = {c.get("id"): c.get("name") for c in cols}
    name_to_id = {c.get("name"): c.get("id") for c in cols}
    art_col = name_to_id.get("Article")
    jp_col = name_to_id.get("Journalist Profile")
    score_col = name_to_id.get("Score")
    fit_col = name_to_id.get("Why They Fit")
    pitch_col = name_to_id.get("Pitch Angle")
    rec_col = name_to_id.get("Recent Articles")
    ai_col = name_to_id.get("AI Analysis")
    for r in rows:
        rid = r.get("id")
        vals = r.get("values") or {}
        def get(col_id):
            v = vals.get(col_id) or {}
            if isinstance(v, dict):
                return v.get("data") if "data" in v else v
            return v
        a = get(art_col) or {}
        jp = get(jp_col) or {}
        sc = get(score_col) or {}
        wf = get(fit_col) or {}
        pa = get(pitch_col) or {}
        rc = get(rec_col) or {}
